css:
:root{
  --green:#23463a;
  --green-2:#2f5d4f;
  --gold:#c7a56f;
  --gold-2:#e8d0a3;
  --cream:#fbf8f2;
  --ink:#17201c;
  --muted:#4f5a55;
  --line:rgba(35,70,58,.10);
  --glass:rgba(255,255,255,.72);
  --shadow-xl:0 28px 80px rgba(25,48,40,.14);
  --shadow-lg:0 18px 50px rgba(25,48,40,.10);
  --shadow-md:0 12px 32px rgba(25,48,40,.08);
  --radius-xl:32px;
  --radius-lg:24px;
}
html{scroll-behavior:smooth}
body{
  background:
    radial-gradient(circle at 12% 10%, rgba(199,165,111,.11), transparent 24rem),
    radial-gradient(circle at 90% 17%, rgba(47,93,79,.10), transparent 28rem),
    linear-gradient(180deg,#fcfaf6 0%,#f8f4ec 52%,#fcfaf6 100%);
  color:var(--ink);
}
body:before{
  content:"";
  position:fixed; inset:0; pointer-events:none; z-index:-1;
  background-image:linear-gradient(rgba(35,70,58,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(35,70,58,.018) 1px,transparent 1px);
  background-size:34px 34px;
  mask-image:linear-gradient(to bottom,rgba(0,0,0,.35),transparent 78%);
}
.container{width:min(1240px,calc(100% - 32px))}
.topbar{
  position:relative; overflow:hidden;
  padding:10px 16px;
  background:linear-gradient(90deg,#18392f,#2f5d4f 48%,#18392f);
  box-shadow:0 8px 25px rgba(24,57,47,.15);
  letter-spacing:.1px;
}
.topbar:after{
  content:""; position:absolute; inset:0; pointer-events:none;
  background:linear-gradient(100deg,transparent 15%,rgba(255,255,255,.13) 50%,transparent 85%);
  transform:translateX(-100%); animation:shine 7s linear infinite;
}
@keyframes shine{to{transform:translateX(100%)}}

.site{
  position:sticky; top:0; z-index:30;
  background:rgba(252,250,246,.82);
  backdrop-filter:blur(18px); -webkit-backdrop-filter:blur(18px);
  border-bottom:1px solid rgba(35,70,58,.08);
}
.site .container{min-height:74px}
.logo{font-size:29px!important;font-weight:900;letter-spacing:-1px;color:var(--green)!important}
.logo span{color:var(--gold)!important}
.menu a{font-weight:800!important;color:#3d4a45!important;transition:.25s ease}
.menu a:hover{color:var(--green)!important}
.hd-wa{
  border:1px solid rgba(35,70,58,.12)!important;
  background:#fff!important;
  color:var(--green)!important;
  box-shadow:0 8px 20px rgba(35,70,58,.07);
}
.cart-btn{
  box-shadow:0 8px 20px rgba(35,70,58,.06);
  border:1px solid rgba(35,70,58,.10)!important;
}

.crumbs{
  margin:20px 0 10px!important;
  color:#7b867f!important;
  font-size:.88rem!important;
}
.crumbs a{font-weight:800;color:var(--green)!important}

.lp-hero{
  position:relative;
  padding:26px 0 84px!important;
  align-items:stretch!important;
}
.lp-hero:before{
  content:""; position:absolute; left:-9vw; top:28px;
  width:28vw; height:28vw; max-width:380px; max-height:380px;
  border:1px solid rgba(199,165,111,.16); border-radius:50%;
  box-shadow:0 0 0 28px rgba(199,165,111,.035),0 0 0 56px rgba(199,165,111,.02);
  pointer-events:none;
}
.pbox{
  position:relative; padding:18px!important;
  border:1px solid rgba(35,70,58,.09)!important;
  border-radius:var(--radius-xl)!important;
  background:rgba(255,255,255,.76)!important;
  box-shadow:var(--shadow-xl)!important;
  backdrop-filter:blur(16px);
}
.gmain{
  min-height:540px!important;
  border-radius:25px!important;
  background:
    radial-gradient(circle at 50% 30%,rgba(255,255,255,.95),transparent 48%),
    linear-gradient(145deg,#f3eee4,#faf7f1)!important;
  border:1px solid rgba(35,70,58,.05);
}
.gmain img{
  transition:transform .7s cubic-bezier(.2,.7,.2,1);
  filter:drop-shadow(0 26px 24px rgba(22,48,39,.13));
}
.pbox:hover .gmain img{transform:scale(1.035) translateY(-5px)}
.pthumbs{margin-top:15px}
.gthumbs{gap:10px!important}
.gthumbs>*{border-radius:16px!important;border:1px solid var(--line)!important;overflow:hidden}
.gthumbs img{width:100%;height:84px;object-fit:cover;cursor:pointer;transition:.2s}
.gthumbs img:hover{opacity:.8}
.gthumbs img.active{border:2px solid var(--gold)!important;opacity:1}
.trust-strip span{
  background:rgba(255,255,255,.88)!important;
  border:1px solid var(--line)!important;
  box-shadow:0 8px 18px rgba(35,70,58,.05);
}

.lp-info{
  display:flex!important; flex-direction:column!important; justify-content:center!important;
  padding:10px 4px 10px 10px;
}
.eyebrow{
  width:max-content;
  padding:8px 14px!important;
  border:1px solid rgba(199,165,111,.26);
  background:linear-gradient(135deg,#f4ecde,#fbf7ef)!important;
  color:var(--green)!important;
  border-radius:999px!important;
  font-weight:900!important;
  box-shadow:0 8px 18px rgba(199,165,111,.08);
}
.lp-info h1{
  font-size:clamp(40px,5vw,68px)!important;
  line-height:1.08!important;
  letter-spacing:-1.8px;
  color:var(--green)!important;
  margin:13px 0 12px!important;
  text-wrap:balance;
}
.lp-sub{
  font-size:clamp(19px,2vw,26px)!important;
  line-height:1.55!important;
  font-weight:900!important;
  color:#27332e!important;
  max-width:700px;
}
.lp-desc{
  font-size:17px!important;
  line-height:1.95!important;
  color:var(--muted)!important;
  max-width:720px;
}
.stars{color:#bb8c36!important}
.stars small{color:#718078!important}
.pd-tags{gap:10px!important}
.tag{
  border:1px solid rgba(35,70,58,.08)!important;
  background:#fff!important;
  border-radius:999px!important;
  padding:9px 13px!important;
  box-shadow:0 7px 17px rgba(35,70,58,.05);
}
.price-box{
  margin:13px 0!important;
  display:flex!important; align-items:center!important; gap:13px!important; flex-wrap:wrap;
}
.price-now{font-size:42px!important;color:var(--green)!important;font-weight:900!important}
.price-old{font-size:20px!important;color:#9b978e!important}
.save-pill{
  background:#edf4ef!important;color:var(--green)!important;border:1px solid rgba(35,70,58,.10);
  padding:6px 10px;border-radius:999px;font-weight:900
}
.deal-bar{
  border:1px solid rgba(199,165,111,.30)!important;
  background:linear-gradient(135deg,#fcf7ed,#fff)!important;
  box-shadow:0 12px 30px rgba(199,165,111,.10)!important;
  border-radius:22px!important;
}
.deal-timer{
  border-radius:16px!important;
  background:var(--green)!important;
  color:#fff!important;
  padding:9px 14px!important;
  font-weight:900!important;
}
.offers{
  display:grid;gap:10px;margin:14px 0;
}
.offer-card{
  border:1px solid rgba(35,70,58,.08);
  border-radius:18px;
  background:#fff;
}
.mini-points{gap:9px!important}
.mini-points>div{
  background:rgba(255,255,255,.86)!important;
  border:1px solid var(--line)!important;
  box-shadow:0 8px 18px rgba(35,70,58,.045)!important;
  border-radius:15px!important;
}
.form{
  position:relative;
  margin-top:18px!important;
  padding:24px!important;
  border-radius:26px!important;
  border:1px solid rgba(35,70,58,.09)!important;
  background:linear-gradient(180deg,rgba(255,255,255,.97),rgba(250,248,242,.96))!important;
  box-shadow:var(--shadow-lg)!important;
}
.form h3{
  font-size:21px!important;color:var(--green)!important;margin-bottom:17px!important
}
.field input,.field select{
  min-height:52px!important;
  border:1px solid rgba(35,70,58,.14)!important;
  background:#fff!important;border-radius:14px!important;
  outline:none!important;
  transition:.22s ease!important;
}
.field input:focus,.field select:focus{
  border-color:rgba(47,93,79,.55)!important;
  box-shadow:0 0 0 4px rgba(47,93,79,.09)!important;
}
.dtype{
  border:1px solid rgba(35,70,58,.08);
  background:#f6f3eb;
  border-radius:15px;
  padding:8px!important;
}
.dtype label{
  background:#fff;border-radius:12px;padding:10px 12px!important;
  border:1px solid transparent;
}
.total-box{
  margin:12px 0!important;
  border-radius:18px!important;
  border:1px solid rgba(35,70,58,.09)!important;
  background:#f8f5ed!important;
  color:var(--ink)!important;
}
.total-box small{color:var(--muted)!important;font-weight:700!important}
.total-box b,.total-box #fee{color:var(--green)!important}
.btn-order,.btn-gold,.lp-btn-gold{
  background:linear-gradient(135deg,#d0ae78,#e7cb9b)!important;
  color:#19231f!important;
  box-shadow:0 14px 28px rgba(199,165,111,.22)!important;
  border-radius:16px!important;
}
.btn-wa,.btn-cart2{
  border-radius:15px!important;
  transition:.25s ease!important;
}
.btn-order:hover,.btn-wa:hover,.btn-cart2:hover,.lp-btn:hover{transform:translateY(-2px)}

.lp-sec{
  position:relative;
  padding:90px 0!important;
}
.lp-sec.alt{
  background:linear-gradient(180deg,rgba(255,255,255,.54),rgba(245,241,233,.58));
  border-top:1px solid rgba(35,70,58,.055);
  border-bottom:1px solid rgba(35,70,58,.055);
}
.lp-grid{gap:48px!important}
.lp-imgcard{
  border-radius:30px!important;
  box-shadow:var(--shadow-xl)!important;
  border:1px solid rgba(35,70,58,.08)!important;
  overflow:hidden!important;
  background:#fff!important;
}
.lp-imgcard img{transition:transform .7s cubic-bezier(.2,.7,.2,1)!important}
.lp-imgcard:hover img{transform:scale(1.035)}
.lp-textcard{
  padding:38px!important;
  border-radius:28px!important;
  border:1px solid rgba(35,70,58,.08)!important;
  box-shadow:var(--shadow-md)!important;
  background:rgba(255,255,255,.82)!important;
  backdrop-filter:blur(10px);
}
.lp-textcard h2,.lp-head h2{
  color:var(--green)!important;
  letter-spacing:-.6px;
}
.lp-textcard h2{font-size:clamp(30px,3vw,44px)!important;line-height:1.2!important}
.lp-textcard p{color:var(--muted)!important;font-size:17px!important}
.lp-bullets{gap:10px!important}
.lp-bullets>div{
  position:relative;padding:14px 16px 14px 18px!important;
  background:#f7f4ed!important;border:1px solid rgba(35,70,58,.07)!important;
  border-radius:16px!important;
}
.lp-bullets>div:before{
  content:"✓";position:absolute;right:auto;left:12px;top:50%;transform:translateY(-50%);
  width:22px;height:22px;border-radius:50%;display:grid;place-items:center;
  background:#e8efe9;color:var(--green);font-weight:900;font-size:12px;
}
[dir="rtl"] .lp-bullets>div{padding-left:45px!important;padding-right:16px!important}
.lp-head{margin-bottom:34px!important;text-align:center}
.lp-head h2{font-size:clamp(31px,3vw,46px)!important}
.lp-head p{color:var(--muted)!important}
.lp-cards{gap:16px!important}
.lp-card{
  border:1px solid rgba(35,70,58,.08)!important;
  border-radius:22px!important;
  background:rgba(255,255,255,.86)!important;
  box-shadow:var(--shadow-md)!important;
  transition:.35s ease!important;
}
.lp-card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg)!important}
.lp-card .ic{
  width:54px;height:54px;border-radius:16px;display:grid;place-items:center;
  background:linear-gradient(135deg,#edf3ee,#f4ecde);
}
.lp-stepnum{
  box-shadow:0 10px 22px rgba(35,70,58,.16);
}
.lp-final{
  position:relative;overflow:hidden;
  border-radius:34px!important;
  padding:58px 30px!important;
  background:
   radial-gradient(circle at 10% 10%,rgba(231,203,155,.22),transparent 25%),
   radial-gradient(circle at 90% 90%,rgba(255,255,255,.07),transparent 26%),
   linear-gradient(135deg,#17392f,#2f5d4f)!important;
  box-shadow:var(--shadow-xl)!important;
}
.lp-final:after{
  content:"";position:absolute;inset:14px;border:1px solid rgba(255,255,255,.10);border-radius:25px;pointer-events:none
}
.lp-final h2{font-size:clamp(31px,4vw,52px)!important;color:#f0d39d!important;line-height:1.2!important}
.lp-final p{font-size:17px!important;color:rgba(255,255,255,.84)!important;max-width:820px}
.lp-btn{
  min-height:56px!important;padding:14px 22px!important;border-radius:16px!important;font-weight:900!important;
}
.lp-btn-green{
  background:rgba(255,255,255,.10)!important;color:#fff!important;
  border:1px solid rgba(255,255,255,.2)!important;
}
.sticky-cta{
  border-top:1px solid rgba(35,70,58,.1)!important;
  background:rgba(252,250,246,.90)!important;
  backdrop-filter:blur(18px)!important;
  box-shadow:0 -10px 28px rgba(35,70,58,.06)!important;
}
footer.site{
  position:relative!important;
  background:#132d25!important;
  color:rgba(255,255,255,.76)!important;
  border-bottom:0!important;
  margin-top:0;
}
footer.site a{color:#f0d39d!important}
footer.site h4{color:#fff!important}
.copy{border-top:1px solid rgba(255,255,255,.10)!important}

/* Avis screenshots */
.reviews-screenshots{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(280px,1fr));
  gap:16px;
  margin-top:20px;
}
.reviews-screenshots img{
  width:100%;
  border-radius:16px;
  box-shadow:0 12px 32px rgba(25,48,40,.12);
  border:1px solid rgba(35,70,58,.08);
  transition:transform .3s ease;
}
.reviews-screenshots img:hover{
  transform:translateY(-4px);
}

@media (max-width:980px){
  .lp-cards[style*="repeat(4"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .lp-cards[style*="repeat(3"]{grid-template-columns:repeat(2,minmax(0,1fr))!important}

  .lp-hero{padding-top:10px!important}
  .gmain{min-height:390px!important}
  .lp-info{padding:8px 0}
  .lp-info h1{font-size:42px!important}
  .lp-sec{padding:68px 0!important}
  .lp-textcard{padding:26px!important}
}
@media (max-width:640px){
  .lp-cards[style*="repeat(4"]{grid-template-columns:1fr!important}
  .lp-cards[style*="repeat(3"]{grid-template-columns:1fr!important}

  .container{width:min(100% - 20px,1240px)}
  .site .container{min-height:66px}
  .menu{display:none!important}
  .hd-wa{display:none!important}
  .crumbs{font-size:.78rem!important}
  .gmain{min-height:330px!important}
  .lp-info h1{font-size:37px!important}
  .lp-sub{font-size:18px!important}
  .lp-desc{font-size:15.5px!important}
  .form{padding:18px!important}
  .lp-sec{padding:56px 0!important}
  .lp-textcard h2{font-size:29px!important}
  .lp-card{padding:20px!important}
  .lp-final{padding:42px 20px!important}
  .reviews-screenshots{grid-template-columns:1fr!important}
}
@media (prefers-reduced-motion:reduce){
  *,*:before,*:after{scroll-behavior:auto!important;animation:none!important;transition:none!important}
}

/* نموذج الطلب العريض */
.order-wide{margin-top:2rem}
.order-wide .form{max-width:none!important;margin-top:0!important}
@media(min-width:960px){
  .order-wide .form{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr));gap:.9rem 1.2rem;align-items:end;padding:26px 32px!important}
  .order-wide .form>h3{grid-column:1/-1;margin:0}
  .order-wide .form .frow{display:contents}
  .order-wide .form .field{margin:0}
  .order-wide .form #desk-wrap{grid-column:span 2}
  .order-wide .form .dtype{grid-column:span 2;margin:0}
  .order-wide .form .coupon-box{grid-column:span 2;margin:0!important;flex-wrap:nowrap!important;align-self:stretch;align-items:center}
  .order-wide .form .coupon-box .btn-cart2{width:auto!important;flex:none;margin:0}
  .order-wide .form #prod-coupon-msg{grid-column:1/-1;margin:0!important;min-height:0!important}
  .order-wide .form .total-box{grid-column:span 2;margin:0;align-self:stretch}
  .order-wide .form .btn-order{grid-column:span 2;margin:0;align-self:stretch;font-size:1.1rem}
  .order-wide .form .btn-wa,.order-wide .form .btn-cart2#add-cart{grid-column:span 2;margin:0}
  .order-wide .form .cod-note{grid-column:1/-1;margin:0}
}

/* أليسوم — ALYSSUM Store · Design System */
:root{
  --bg:#FBF8F2; --card:#FFFFFF; --ink:#1C2420; --muted:#566360;
  --green:#173F35; --green-2:#0F2E26; --gold:#C8A24B; --gold-2:#E4C87F;
  --red:#D64545; --ok:#157A55; --line:#EAE3D6; --r:18px;
  --shadow:0 10px 30px rgba(23,63,53,.08); --shadow-lg:0 24px 60px rgba(23,63,53,.16);
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:hidden;width:100%}
body{font-family:'Cairo','Segoe UI',Tahoma,sans-serif;background:var(--bg);color:var(--ink);direction:rtl;line-height:1.7;overflow-x:hidden;width:100%}
img{max-width:100%;display:block}
:where(img[width][height]){height:auto}
a{text-decoration:none;color:inherit}
button{font-family:inherit;cursor:pointer;border:none}
.container{width:min(1180px,92%);margin-inline:auto}

/* ── Top bar ── */
.topbar{background:var(--green);color:#F3E9D2;font-size:.85rem;padding:.45rem 0;text-align:center}
.topbar b{color:var(--gold-2)}

/* ── Header ── */
header.site{position:sticky;top:0;z-index:50;background:rgba(251,248,242,.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.site .container{display:flex;align-items:center;gap:1rem;padding:.7rem 0}
.logo{font-size:1.5rem;font-weight:900;color:var(--green);letter-spacing:.5px}
.logo span{color:#8a6a1a}
nav.menu{display:flex;gap:1.4rem;margin-inline-start:auto;font-weight:700;font-size:.95rem}
nav.menu a{color:var(--green);opacity:.85}
nav.menu a:hover{opacity:1;color:var(--gold)}
@media(max-width:860px){nav.menu{display:none}}
@media(max-width:500px){.hd-wa{padding:.5rem .8rem;font-size:0}.hd-wa::before{content:"💬";font-size:1.2rem}}
.hd-wa{background:var(--ok);color:#fff;padding:.5rem 1.1rem;border-radius:999px;font-weight:800;display:flex;align-items:center;gap:.4rem}
.cart-btn{position:relative;background:var(--green);color:#fff;width:44px;height:44px;border-radius:14px;display:grid;place-items:center}
.cart-count{position:absolute;top:-6px;left:-6px;background:var(--red);color:#fff;font-size:.7rem;font-weight:800;min-width:20px;height:20px;border-radius:999px;display:grid;place-items:center;padding:0 4px}

/* ── Hero ── */
.hero{background:radial-gradient(1200px 500px at 80% -10%,#E9DDBE,transparent),linear-gradient(160deg,var(--green-2),var(--green));color:#fff;padding:4rem 0;position:relative;overflow:hidden}
.hero::after{content:"";position:absolute;inset:auto -120px -160px auto;width:420px;height:420px;border-radius:50%;background:rgba(200,162,75,.14)}
.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:2.6rem;align-items:center;position:relative;z-index:1}
@media(max-width:900px){.hero-grid{grid-template-columns:1fr}}
.hero h1{font-size:clamp(1.9rem,4.5vw,3.2rem);font-weight:900;line-height:1.35}
.hero h1 em{color:var(--gold-2);font-style:normal}
.hero p{color:#D9E2DD;margin:1rem 0 1.6rem;max-width:520px;font-size:1.08rem}
.hero-cta{display:flex;gap:.9rem;flex-wrap:wrap}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;font-weight:800;border-radius:14px;padding:.95rem 2rem;font-size:1.05rem;transition:.2s}
.btn-gold{background:linear-gradient(135deg,var(--gold),#B08A36);color:#fff;box-shadow:0 12px 26px rgba(200,162,75,.4)}
.btn-gold:hover{transform:translateY(-2px);box-shadow:0 16px 32px rgba(200,162,75,.5)}
.btn-ghost{border:2px solid rgba(255,255,255,.4);color:#fff}
.btn-ghost:hover{background:rgba(255,255,255,.1)}
.hero-trust{margin-top:1.3rem}
.hero-trust span{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.22);color:#F1EBDD}
.hero-stats{display:flex;gap:2.2rem;margin-top:2rem;flex-wrap:wrap}
.hero-stats div b{font-size:1.5rem;color:var(--gold-2)}
.hero-stats div small{display:block;color:#C7D3CD}
.hero-media{position:relative}
.hero-imgbox{border-radius:28px;overflow:hidden;aspect-ratio:1/1;box-shadow:var(--shadow-lg);border:1px solid rgba(255,255,255,.15)}
.hero-imgbox img{width:100%;height:100%;object-fit:cover}
.hero-badge{position:absolute;display:flex;align-items:center;gap:.6rem;background:#fff;color:var(--ink);border-radius:16px;padding:.7rem 1rem;box-shadow:var(--shadow-lg);font-size:1.3rem;font-weight:900}
.hero-badge b{color:var(--green);font-size:.95rem}
.hero-badge small{display:block;color:var(--muted);font-weight:700;font-size:.72rem}
.hero-badge.b1{top:-14px;right:-14px}
.hero-badge.b2{bottom:-14px;left:-14px}
@media(max-width:900px){.hero-badge{position:static;display:inline-flex;margin:.6rem .5rem 0 0}}

/* ── Sections ── */
section{padding:3.6rem 0}
.sec-title{text-align:center;margin-bottom:2.2rem}
.sec-title h2{font-size:1.9rem;font-weight:900;color:var(--green)}
.sec-title p{color:var(--muted)}
.sec-title .kicker{color:var(--gold);font-weight:800;letter-spacing:2px;font-size:.8rem}

/* ── Category chips ── */
.chips{display:flex;gap:.6rem;flex-wrap:wrap;justify-content:center;margin-bottom:2rem}
.chip{padding:.5rem 1.3rem;border-radius:999px;background:#fff;border:1.5px solid var(--line);font-weight:700;color:var(--muted);transition:.15s}
.chip.active,.chip:hover{background:var(--green);color:#fff;border-color:var(--green)}

/* ── Product grid ── */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(255px,1fr));gap:1.4rem}
.card{background:var(--card);border-radius:var(--r);overflow:hidden;box-shadow:var(--shadow);border:1px solid var(--line);transition:.25s;display:flex;flex-direction:column}
.card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg)}
.card .thumb{position:relative;aspect-ratio:1;background:#F4EFE6;overflow:hidden}
.card .thumb img{width:100%;height:100%;object-fit:cover;transition:.5s}
.card:hover .thumb img{transform:scale(1.06)}
.badge-off{position:absolute;top:12px;right:12px;background:#b83232;color:#fff;font-weight:800;font-size:.78rem;padding:.25rem .7rem;border-radius:999px}
.ribbon-oos{position:absolute;inset:0;background:rgba(28,36,32,.55);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1.05rem;text-align:center;z-index:2}
.card.oos .thumb img{filter:grayscale(60%)}
.oos-warning{background:#FBEAEA;border:1px solid var(--red);color:#8A2424;border-radius:10px;padding:.9rem 1.1rem;font-weight:700;margin:1rem 0;text-align:center}
.card .body{padding:1.1rem 1.2rem 1.3rem;display:flex;flex-direction:column;gap:.5rem;flex:1}
.card h3{font-size:1.02rem;font-weight:800;color:var(--ink)}
.stars{color:var(--gold);font-size:.85rem;letter-spacing:2px}
.stars small{color:var(--muted);letter-spacing:0}
.price-row{display:flex;align-items:baseline;gap:.6rem;margin-top:auto}
.price{font-size:1.35rem;font-weight:900;color:var(--green)}
.old{color:var(--muted);text-decoration:line-through;font-size:.92rem}
.card .cta{margin-top:.6rem;background:var(--green);color:#fff;border-radius:12px;padding:.7rem;font-weight:800;text-align:center;transition:.2s}
.card .cta:hover{background:var(--gold)}

/* ── Features ── */
.feat{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:1.6rem;text-align:center;box-shadow:var(--shadow)}
.feat .ic{font-size:2rem;margin-bottom:.6rem}
.feat h3{font-size:1.05rem;font-weight:800;color:var(--green)}
.feat p{color:var(--muted);font-size:.92rem}
.feats{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1.3rem}

/* ── Landing produit ── */
.crumbs{font-size:.85rem;color:var(--muted);padding:1rem 0}
.crumbs a{color:var(--green);font-weight:700}
.pd{display:grid;grid-template-columns:1.05fr 1fr;gap:2.6rem;align-items:start}
@media(max-width:900px){.pd{grid-template-columns:1fr}}
.gallery{position:sticky;top:90px}
@media(max-width:900px){.gallery{position:static}}
.gmain{border-radius:var(--r);overflow:hidden;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);aspect-ratio:1}
.gmain img{width:100%;height:100%;object-fit:cover}
.gthumbs{display:flex;gap:.7rem;margin-top:.8rem}
.gthumbs img{width:74px;height:74px;border-radius:12px;object-fit:cover;border:2px solid var(--line);cursor:pointer;opacity:.7;transition:.15s}
.gthumbs img.on,.gthumbs img:hover{border-color:var(--gold);opacity:1}
.pd-info h1{font-size:1.75rem;font-weight:900;color:var(--green);line-height:1.5}
.pd-tags{display:flex;gap:.5rem;flex-wrap:wrap;margin:.7rem 0}
.tag{background:#F1EBDD;color:#7A6A45;font-size:.75rem;font-weight:700;padding:.28rem .8rem;border-radius:999px}
.pd-price{display:flex;align-items:baseline;gap:.9rem;margin:1rem 0 .2rem}
.pd-price .price{font-size:2.3rem}
.save-pill{background:var(--red);color:#fff;font-weight:800;border-radius:999px;padding:.3rem .9rem;font-size:.85rem}

.offers{display:grid;grid-template-columns:repeat(3,1fr);gap:.7rem;margin:1.2rem 0}
.offer{border:2px solid var(--line);border-radius:14px;padding:.85rem .6rem;text-align:center;cursor:pointer;background:#fff;transition:.15s;position:relative}
.offer.on{border-color:var(--gold);background:#FDF8EC;box-shadow:0 6px 18px rgba(200,162,75,.25)}
.offer .q{font-weight:900;font-size:1.05rem;color:var(--green)}
.offer .p{font-weight:900;color:var(--ink);margin-top:.15rem}
.offer .u{font-size:.75rem;color:var(--muted)}
.offer .best{position:absolute;top:-11px;right:50%;transform:translateX(50%);background:var(--gold);color:#1C2420;font-size:.68rem;font-weight:800;padding:.14rem .6rem;border-radius:999px;white-space:nowrap}

.form{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:1.6rem;box-shadow:var(--shadow);margin-top:1.4rem}
.form h3{font-weight:900;color:var(--green);margin-bottom:1rem;display:flex;align-items:center;gap:.5rem}
.frow{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}
@media(max-width:560px){.frow{grid-template-columns:1fr}}
.field{display:flex;flex-direction:column;gap:.3rem;margin-bottom:.85rem}
.field label{font-size:.85rem;font-weight:800;color:var(--ink)}
.field input,.field select{border:1.5px solid var(--line);border-radius:12px;padding:.75rem .95rem;font-family:inherit;font-size:1rem;background:#FDFCFA;transition:.15s}
.field input:focus,.field select:focus{outline:none;border-color:var(--gold);box-shadow:0 0 0 4px rgba(200,162,75,.15)}
.dtype{display:grid;grid-template-columns:1fr 1fr;gap:.7rem;margin-bottom:.9rem}
.dtype label{border:2px solid var(--line);border-radius:12px;padding:.7rem;text-align:center;font-weight:800;cursor:pointer;transition:.15s;font-size:.92rem}
.dtype input{display:none}
.dtype input:checked+span{color:var(--green)}
.dtype label:has(input:checked){border-color:var(--green);background:#EFF6F3}
.total-box{background:var(--green-2);color:#fff;border-radius:14px;padding:1rem 1.3rem;display:flex;justify-content:space-between;align-items:center;margin:.4rem 0 1rem}
.total-box b{font-size:1.5rem;color:var(--gold-2)}
.total-box small{display:block;color:#B9C8C1;font-weight:400}
.btn-order{width:100%;background:linear-gradient(135deg,var(--gold),#B08A36);color:#fff;font-size:1.15rem;padding:1.05rem;border-radius:14px;font-weight:900;box-shadow:0 14px 30px rgba(200,162,75,.4);transition:.2s}
.btn-order:hover{transform:translateY(-2px)}
.btn-wa{width:100%;background:var(--ok);color:#fff;margin-top:.7rem;padding:.95rem;border-radius:14px;font-weight:800;display:flex;align-items:center;justify-content:center;gap:.5rem}
.btn-cart2{width:100%;background:#fff;border:2px solid var(--green);color:var(--green);margin-top:.7rem;padding:.85rem;border-radius:14px;font-weight:800}
.cod-note{display:flex;gap:.6rem;align-items:center;justify-content:center;background:#EFF6F3;border:1px dashed var(--ok);color:var(--green);border-radius:12px;padding:.65rem;font-weight:800;font-size:.9rem;margin-top:.9rem}

.benefits{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:1.6rem;margin-top:1.6rem}
.benefits li{list-style:none;display:flex;gap:.6rem;padding:.45rem 0;color:#3A4540}
.benefits li::before{content:"✔";color:var(--ok);font-weight:900}

.trust{display:flex;gap:1rem;flex-wrap:wrap;margin-top:1.2rem}
.trust div{flex:1;min-width:140px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:.9rem;text-align:center;font-weight:800;color:var(--green);font-size:.88rem}
.trust div span{display:block;font-size:1.5rem;margin-bottom:.3rem}

/* ── Sticky mobile CTA ── */
.sticky-cta{position:fixed;bottom:0;right:0;left:0;z-index:40;background:#fff;border-top:1px solid var(--line);box-shadow:0 -8px 24px rgba(0,0,0,.08);display:none;padding:.7rem 4%;gap:.8rem;align-items:center}
@media(max-width:900px){.sticky-cta{display:flex}}
.sticky-cta .p{font-weight:900;color:var(--green);font-size:1.15rem}
.sticky-cta .btn{flex:1;padding:.8rem;font-size:1rem}

/* ── Cart drawer ── */
.drawer-bg{position:fixed;inset:0;background:rgba(15,25,21,.5);z-index:60;opacity:0;pointer-events:none;transition:.25s}
.drawer{position:fixed;top:0;left:0;bottom:0;width:min(420px,92vw);background:#fff;z-index:61;transform:translateX(-100%);transition:.3s;display:flex;flex-direction:column}
.drawer.open{transform:none}
.drawer-bg.open{opacity:1;pointer-events:auto}
.drawer h3{padding:1.2rem 1.4rem;border-bottom:1px solid var(--line);font-weight:900;color:var(--green)}
.drawer .items{flex:1;overflow:auto;padding:1rem 1.4rem}
.citem{display:flex;gap:.8rem;align-items:center;border:1px solid var(--line);border-radius:14px;padding:.7rem;margin-bottom:.8rem}
.citem img{width:64px;height:64px;border-radius:10px;object-fit:cover}
.citem .t{flex:1;font-weight:800;font-size:.92rem}
.qty{display:flex;align-items:center;gap:.5rem}
.qty button{width:28px;height:28px;border-radius:8px;background:var(--green);color:#fff;font-weight:900}
.drawer .foot{padding:1.2rem 1.4rem;border-top:1px solid var(--line)}
.drawer .tot{display:flex;justify-content:space-between;font-weight:900;font-size:1.1rem;margin-bottom:.8rem;color:var(--green)}

/* ── Agent ── */
.agent-fab{position:fixed;bottom:22px;left:22px;z-index:70;width:62px;height:62px;border-radius:50%;background:linear-gradient(135deg,var(--green),var(--green-2));color:#fff;display:grid;place-items:center;box-shadow:0 14px 34px rgba(23,63,53,.45);cursor:pointer;border:2px solid var(--gold)}
.agent-fab::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid rgba(200,162,75,.5);animation:pulse 2s infinite}
@keyframes pulse{0%{transform:scale(.9);opacity:1}100%{transform:scale(1.25);opacity:0}}
.agent-panel{position:fixed;bottom:96px;left:22px;z-index:70;width:min(370px,calc(100vw - 32px));height:520px;max-height:72vh;background:#fff;border-radius:20px;box-shadow:var(--shadow-lg);display:flex;flex-direction:column;overflow:hidden;transform:translateY(20px);opacity:0;pointer-events:none;transition:.25s;border:1px solid var(--line)}
.agent-panel.open{transform:none;opacity:1;pointer-events:auto}
.agent-head{background:linear-gradient(135deg,var(--green),var(--green-2));color:#fff;padding:.95rem 1.1rem;display:flex;align-items:center;gap:.7rem}
.agent-head .av{width:38px;height:38px;border-radius:50%;background:var(--gold);display:grid;place-items:center;font-size:1.2rem}
.agent-head b{font-size:.98rem}
.agent-head small{display:block;color:#C7D3CD;font-size:.72rem}
.agent-head .x{margin-inline-start:auto;background:none;color:#fff;font-size:1.3rem}
.agent-body{flex:1;overflow:auto;padding:1rem;display:flex;flex-direction:column;gap:.6rem;background:#F7F4ED}
.msg{max-width:86%;padding:.6rem .9rem;border-radius:14px;font-size:.92rem;line-height:1.6;animation:in .25s}
@keyframes in{from{opacity:0;transform:translateY(6px)}}
.msg.bot{background:#fff;border:1px solid var(--line);align-self:flex-start;border-bottom-right-radius:4px}
.msg.user{background:var(--green);color:#fff;align-self:flex-start;border-bottom-left-radius:4px;margin-inline-start:auto}
.msg .mini{display:block;margin-top:.5rem;background:#FDF8EC;border:1px solid var(--gold-2);border-radius:10px;padding:.5rem .7rem;color:var(--ink);font-weight:700}
.msg .mini b{color:var(--green)}
.agent-input{display:flex;gap:.5rem;padding:.8rem;border-top:1px solid var(--line);background:#fff}
.agent-input input{flex:1;border:1.5px solid var(--line);border-radius:999px;padding:.6rem 1rem;font-family:inherit;font-size:.95rem}
.agent-input input:focus{outline:none;border-color:var(--gold)}
.agent-input button{width:44px;height:44px;border-radius:50%;background:var(--green);color:#fff;font-size:1.1rem}
.typing{display:flex;gap:4px;padding:.4rem .2rem}
.typing i{width:7px;height:7px;border-radius:50%;background:#B9C8C1;animation:tp 1s infinite}
.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}
@keyframes tp{0%,100%{transform:none;opacity:.5}50%{transform:translateY(-4px);opacity:1}}

/* ── FAQ ── */
.faq details{background:#fff;border:1px solid var(--line);border-radius:14px;margin-bottom:.7rem;padding:1rem 1.3rem}
.faq summary{font-weight:800;color:var(--green);cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center}
.faq summary::after{content:"+";font-size:1.3rem;color:var(--gold)}
.faq details[open] summary::after{content:"−"}
.faq p{color:var(--muted);margin-top:.6rem;font-size:.95rem}

/* ── Footer ── */
footer.site{background:var(--green-2);color:#C7D3CD;padding:3rem 0 1.5rem;margin-top:3rem}
footer.site h4,footer.site .ft-h{color:#fff;font-weight:900;margin-bottom:.8rem;font-size:1rem}
.fgrid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:2rem}
@media(max-width:760px){.fgrid{grid-template-columns:1fr}}
footer a:hover{color:var(--gold-2)}
.copy{text-align:center;border-top:1px solid rgba(255,255,255,.1);margin-top:2rem;padding-top:1.2rem;font-size:.85rem}

/* ── Reviews ── */
.reviews{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1.2rem}
.review{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:1.3rem;box-shadow:var(--shadow)}
.review .who{display:flex;align-items:center;gap:.7rem;margin-top:.8rem;font-weight:800;color:var(--green);font-size:.9rem}
.review .who i{width:38px;height:38px;border-radius:50%;background:var(--green);color:#fff;display:grid;place-items:center;font-style:normal}


/* ════════ صفحة المنتج — Landing Page ════════ */
.lp-hero{padding:2rem 0 3rem}
.pd2{display:grid;grid-template-columns:1fr 1fr;gap:2.4rem;align-items:start}
@media(max-width:900px){.pd2{grid-template-columns:1fr}}
.pbox{background:#fff;border:1px solid var(--line);border-radius:28px;box-shadow:var(--shadow);padding:18px}
.pbox .gmain{border:none;box-shadow:none;background:#F4EFE6;border-radius:20px}
.pthumbs{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.pthumbs .gthumbs{display:contents}
.pthumbs .gthumbs img{width:100%;height:84px;border-radius:14px}
@media(max-width:560px){.pthumbs .gthumbs img{height:64px}}
.eyebrow{display:inline-block;background:#EFF6F3;color:var(--green);padding:.35rem 1rem;border-radius:999px;font-size:.78rem;font-weight:800;margin-bottom:.8rem}
.lp-info h1{font-size:clamp(1.5rem,3vw,2.1rem);font-weight:900;color:var(--green);line-height:1.45}
.lp-sub{font-size:1.12rem;font-weight:800;margin:.4rem 0;color:var(--ink)}
.lp-desc{color:var(--muted);font-size:1rem;margin-bottom:.8rem}
.price-box{display:flex;align-items:baseline;gap:.9rem;flex-wrap:wrap;margin:.6rem 0}
.price-now{font-size:2.2rem;font-weight:900;color:var(--green)}
.price-old{font-size:1.15rem;color:var(--muted);text-decoration:line-through}
.deal-bar{display:flex;align-items:center;gap:.8rem;background:linear-gradient(135deg,#FFF3E2,#FDEBD3);border:1.5px dashed var(--gold);border-radius:16px;padding:.8rem 1.1rem;margin:1rem 0;flex-wrap:wrap}
.deal-bar .gift{font-size:1.6rem}
.deal-bar b{color:var(--green);font-size:1.02rem}
.deal-timer{font-size:1.35rem;font-weight:900;color:var(--red);letter-spacing:2px;font-variant-numeric:tabular-nums;direction:ltr}
.mini-points{display:grid;gap:.55rem;margin:1.1rem 0}
.mini-points div{background:#fff;border:1px solid var(--line);border-radius:14px;padding:.6rem 1rem;font-weight:800;color:#3A4540;box-shadow:var(--shadow);font-size:.95rem}
.mini-points div::before{content:"✔ ";color:var(--ok);font-weight:900}
.cta-row{display:flex;gap:.7rem;flex-wrap:wrap;margin:.6rem 0 1rem}
.lp-btn{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:.8rem 1.8rem;border-radius:999px;font-family:inherit;font-size:1rem;font-weight:900;transition:.2s;cursor:pointer;border:none}
.lp-btn-gold{background:linear-gradient(135deg,var(--gold),#B08A36);color:#fff;box-shadow:0 10px 24px rgba(200,162,75,.35)}
.lp-btn-ghost{background:#fff;color:var(--green);border:2px solid var(--line)}
.lp-btn-green{background:var(--ok);color:#fff}
.lp-btn:hover{transform:translateY(-2px)}
.trust-strip{display:flex;flex-wrap:wrap;gap:.55rem;margin-top:.9rem}
.trust-strip span{background:#fff;border:1px solid var(--line);border-radius:999px;padding:.4rem .95rem;font-size:.8rem;color:var(--muted);font-weight:800}

/* أقسام الصفحة */
.lp-sec{padding:2.8rem 0}
.lp-sec.alt{background:#F4EFE6}
.lp-head{text-align:center;margin-bottom:2rem}
.lp-head h2{font-size:clamp(1.5rem,3vw,2.1rem);font-weight:900;color:var(--green)}
.lp-head p{color:var(--muted);max-width:680px;margin:.4rem auto 0}
.lp-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.8rem;align-items:center}
@media(max-width:900px){.lp-grid{grid-template-columns:1fr}}
.lp-imgcard{border-radius:26px;overflow:hidden;min-height:340px;box-shadow:var(--shadow-lg);background:#fff}
.lp-imgcard img{width:100%;height:100%;min-height:340px;object-fit:cover}
.lp-textcard{background:#fff;border:1px solid var(--line);border-radius:26px;padding:2rem;box-shadow:var(--shadow)}
.lp-textcard h2{font-size:clamp(1.35rem,2.6vw,1.8rem);color:var(--green);font-weight:900;margin-bottom:.7rem}
.lp-textcard p{color:var(--muted);margin-bottom:1rem}
.lp-bullets{display:grid;gap:.6rem}
.lp-bullets div{background:#F9F7F2;border:1px solid var(--line);border-radius:14px;padding:.6rem 1rem;font-weight:800;color:#3A4540;font-size:.95rem}
.lp-bullets div::before{content:"✔ ";color:var(--ok);font-weight:900}
.lp-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:1.1rem}
@media(max-width:900px){.lp-cards{grid-template-columns:1fr}}
.lp-card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:1.6rem;box-shadow:var(--shadow);transition:.2s}
.lp-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.lp-card .ic{font-size:2rem;margin-bottom:.5rem}
.lp-card h3{font-size:1.1rem;font-weight:900;color:var(--green);margin-bottom:.4rem}
.lp-card p{color:var(--muted);font-size:.93rem}
.lp-stepnum{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;background:var(--green);color:#fff;font-size:1.2rem;font-weight:900;margin-bottom:.8rem}
.lp-final{background:linear-gradient(135deg,var(--green-2),var(--green));color:#fff;border-radius:30px;padding:3rem 1.6rem;text-align:center;box-shadow:var(--shadow-lg);margin:2.5rem 0}
.lp-final h2{font-size:clamp(1.5rem,3vw,2.2rem);color:var(--gold-2);font-weight:900;margin-bottom:.7rem}
.lp-final p{max-width:700px;margin:0 auto 1.4rem;color:rgba(255,255,255,.88)}
.lp-testis{display:grid;grid-template-columns:repeat(3,1fr);gap:1.1rem}
@media(max-width:900px){.lp-testis{grid-template-columns:1fr}}


/* ════════ قسم الصفحة الرئيسية الجديد 2026 (تجديد شامل حديث) ════════
   إضافات فقط — لا تُغيّر أياً من القواعد أعلاه المستعملة في صفحات المنتجات الـ29
   أو في شبكة المنتجات المشتركة (.card). آمنة للتوسعة لاحقاً بنفس الروح. */

/* مرساة التمرير حتى لا يغطي الهيدر اللاصق عناوين الأقسام عند الضغط على روابط القائمة */
section[id]{scroll-margin-top:84px}

/* شريط ثقة صغير قابل لإعادة الاستخدام (مستعمل في الهيرو والقسم الختامي) */
.trust-strip{display:flex;flex-wrap:wrap;gap:.55rem}
.trust-strip span{background:#fff;border:1px solid var(--line);border-radius:999px;padding:.4rem .95rem;font-size:.8rem;color:var(--muted);font-weight:800}

/* بطاقات «تسوّق حسب الفئة» */
.shop-cats{display:grid;grid-template-columns:repeat(6,1fr);gap:1.1rem}
@media(max-width:960px){.shop-cats{grid-template-columns:repeat(3,1fr)}}
@media(max-width:560px){.shop-cats{grid-template-columns:repeat(2,1fr)}}
.shop-cat{position:relative;aspect-ratio:1/1;border-radius:20px;overflow:hidden;background-size:cover;background-position:center;background-color:var(--card);box-shadow:var(--shadow);border:1px solid var(--line);transition:.25s;font-family:inherit;padding:0;-webkit-appearance:none;appearance:none}
.shop-cat:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg)}
.shop-cat::before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(10,32,26,.92) 0%,rgba(10,32,26,.75) 32%,rgba(10,32,26,.15) 68%,rgba(10,32,26,0) 100%);transition:.25s}
.shop-cat:hover::before{background:linear-gradient(0deg,rgba(163,124,42,.94) 0%,rgba(10,32,26,.78) 34%,rgba(10,32,26,.2) 70%,rgba(10,32,26,0) 100%)}
.shop-cat span{position:absolute;inset-inline:0;bottom:0;padding:.9rem .5rem;color:#fff;font-weight:900;font-size:.95rem;text-align:center;text-shadow:0 1px 4px rgba(0,0,0,.55)}
@media(max-width:560px){.shop-cat span{font-size:.85rem}}

/* شريط «الأكثر مبيعاً» — يعيد استعمال .card و.grid، فقط يضيف شريط تمييز */
.ribbon-best{position:absolute;top:12px;left:12px;background:linear-gradient(135deg,var(--gold),#B08A36);color:#fff;font-weight:800;font-size:.72rem;padding:.25rem .7rem;border-radius:999px;box-shadow:0 6px 14px rgba(200,162,75,.4)}

/* لقطات حقيقية من محادثات الزبائن (نفس الأسلوب المستعمل في صفحات المنتجات) */
.reviews-screenshots{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-top:1.6rem}
.reviews-screenshots img{width:100%;border-radius:16px;box-shadow:var(--shadow);border:1px solid var(--line);transition:.25s}
.reviews-screenshots img:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.shots-caption{text-align:center;color:var(--muted);font-size:.85rem;margin-top:.9rem}

/* حركات ظهور خفيفة عند التمرير */
.reveal{opacity:0;transform:translateY(22px);transition:opacity .6s ease,transform .6s ease}
.reveal.show{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}

/* مبادرة الوكيل: رسالة ترحيب صغيرة فوق الأيقونة (لا تغطي الصفحة) + أزرار سريعة */
.agent-teaser{position:fixed;bottom:96px;left:22px;z-index:71;width:min(310px,calc(100vw - 44px));background:#fff;border:1px solid var(--gold-2);border-radius:18px 18px 18px 4px;box-shadow:var(--shadow-lg);padding:.9rem 1rem .8rem;animation:agentTeaserIn .4s ease;font-size:.92rem;line-height:1.65;cursor:pointer}
.agent-teaser .tx{position:absolute;top:4px;right:8px;background:none;border:0;color:var(--muted);font-size:1rem;cursor:pointer;padding:2px 6px}
.agent-teaser .tt{padding-top:.2rem}
@keyframes agentTeaserIn{from{opacity:0;transform:translateY(10px)}}
.agent-chips{display:flex;flex-wrap:wrap;gap:.4rem;margin-top:.6rem}
.agent-chips .chip{background:#F4EFE4;border:1px solid var(--gold-2);color:var(--green);border-radius:999px;padding:.35rem .8rem;font-family:inherit;font-size:.82rem;font-weight:700;cursor:pointer}
.agent-chips .chip:hover{background:#fff}
.agent-chips .chip.gold{background:var(--gold);border-color:var(--gold);color:#fff}
.msg.cta{background:transparent;border:0;padding:0}

/* عدّاد «يشاهدون الآن» البارز في صفحة المنتج */
.tag.live-badge{background:linear-gradient(135deg,#fff3f0,#ffe9e4);border:1.5px solid #f3b3a8;color:#b3261e;font-weight:800;font-size:1.02rem;padding:.5rem 1rem;border-radius:999px;display:inline-flex;align-items:center;gap:.5rem;box-shadow:0 6px 18px rgba(179,38,30,.12)}
.tag.live-badge b{font-size:1.25rem;font-weight:900;color:#b3261e;min-width:1.4ch;text-align:center}
.live-dot{width:11px;height:11px;border-radius:50%;background:#e03b2f;display:inline-block;box-shadow:0 0 0 0 rgba(224,59,47,.6);animation:liveDot 1.4s infinite}
@keyframes liveDot{70%{box-shadow:0 0 0 9px rgba(224,59,47,0)}100%{box-shadow:0 0 0 0 rgba(224,59,47,0)}}

/* المنتجات المتغيّرة والمجمّعة */
.variant-box{margin:.9rem 0;display:grid;gap:.8rem}
.v-name{font-weight:800;margin-bottom:.35rem;color:var(--green)}
.v-vals{display:flex;flex-wrap:wrap;gap:.5rem}
.v-chip{border:1.5px solid var(--line);background:#fff;border-radius:999px;padding:.45rem 1.05rem;font-weight:800;cursor:pointer;font-family:inherit;color:var(--ink);transition:.15s}
.v-chip:hover{border-color:var(--gold)}
.v-chip.on{background:var(--green);border-color:var(--green);color:#fff}
.v-chip.off{opacity:.4;text-decoration:line-through;cursor:not-allowed}
.v-hint{font-size:.85rem;color:var(--muted)}
.group-box{display:grid;gap:.6rem;margin:.9rem 0}
.g-row{display:flex;align-items:center;gap:.8rem;background:#fff;border:1.5px solid var(--line);border-radius:14px;padding:.6rem .8rem}
.g-row img{width:58px;height:58px;border-radius:10px;object-fit:cover;flex:none}
.g-t{flex:1;display:flex;flex-direction:column;min-width:0}
.g-t small{color:var(--muted)}
.g-q{display:flex;align-items:center;gap:.5rem}
.g-q button{width:36px;height:36px;border-radius:50%;border:1.5px solid var(--line);background:#fff;font-size:1.2rem;font-weight:800;cursor:pointer;font-family:inherit}
.g-q button:disabled{opacity:.4;cursor:not-allowed}
.g-q b{min-width:1.5rem;text-align:center}

/* ── حسابي + تثبيت الموقع ── */
.acc-btn{position:relative;background:#fff;color:var(--green);width:44px;height:44px;border-radius:14px;display:grid;place-items:center;font-size:1.15rem;border:1.5px solid var(--line);margin-inline-start:.4rem}
.acc-btn.on::after{content:"";position:absolute;top:6px;inset-inline-end:6px;width:10px;height:10px;border-radius:50%;background:var(--ok);border:2px solid #fff}
.acc-bg{position:fixed;inset:0;background:rgba(15,46,38,.55);z-index:120;display:none;align-items:center;justify-content:center;padding:1rem;backdrop-filter:blur(3px)}
.acc-bg.open{display:flex}
.acc-box{background:#fff;border-radius:22px;width:min(460px,100%);max-height:92vh;overflow:auto;padding:1.6rem 1.3rem 1.3rem;position:relative;box-shadow:var(--shadow-lg)}
.acc-x{position:absolute;top:.7rem;inset-inline-start:.7rem;width:34px;height:34px;border-radius:50%;background:var(--bg);color:var(--muted);font-size:.95rem}
.acc-box h3{color:var(--green);font-size:1.25rem;margin-bottom:.2rem;padding-inline-start:2.2rem}
.acc-box h4{color:var(--green);margin:1.1rem 0 .5rem}
.acc-sub{color:var(--muted);font-size:.9rem;margin-bottom:.9rem}
.acc-tabs{display:flex;gap:.4rem;background:var(--bg);padding:.25rem;border-radius:14px;margin-bottom:1rem}
.acc-tabs button{flex:1;padding:.55rem;border-radius:11px;background:transparent;font-weight:800;color:var(--muted)}
.acc-tabs button.on{background:#fff;color:var(--green);box-shadow:0 2px 8px rgba(23,63,53,.1)}
.acc-box form label{display:block;font-weight:700;font-size:.85rem;color:var(--ink);margin-bottom:.7rem}
.acc-box form input,.acc-box form select{display:block;width:100%;margin-top:.25rem;padding:.7rem .8rem;border:1.5px solid var(--line);border-radius:12px;font:inherit;background:#fff}
.acc-box form input:focus,.acc-box form select:focus{outline:none;border-color:var(--gold)}
.acc-row{display:grid;grid-template-columns:1fr 1fr;gap:.6rem}
.acc-go{width:100%;margin-top:.2rem}
.acc-msg{min-height:1.2rem;font-size:.85rem;font-weight:700;margin:.2rem 0 .6rem;color:var(--muted)}
.acc-msg.bad{color:var(--red)} .acc-msg.ok{color:var(--ok)}
.acc-note{font-size:.78rem;color:var(--muted);text-align:center;margin-top:.7rem}
.acc-done{text-align:center}
.acc-done h3{padding:0}
.acc-ok{font-size:2.6rem;line-height:1}
.acc-install{background:linear-gradient(135deg,#F6EFD9,#FBF8F2);border:1.5px solid var(--gold-2);border-radius:16px;padding:1rem;margin:.8rem 0;text-align:center}
.acc-install .ai-t{font-weight:900;color:var(--green);margin-bottom:.2rem}
.acc-install p{font-size:.85rem;color:var(--muted);margin-bottom:.7rem}
.ai-steps{display:none;margin-top:.7rem;font-size:.85rem;line-height:1.8;background:#fff;border-radius:12px;padding:.7rem;text-align:right}
.acc-ord{border:1.5px solid var(--line);border-radius:14px;padding:.7rem .8rem;margin-bottom:.55rem}
.ao-h,.ao-f{display:flex;justify-content:space-between;gap:.5rem;font-size:.85rem}
.ao-h span{font-weight:800}
.ao-i{font-size:.85rem;color:var(--muted);margin:.35rem 0}
.ao-t{font-size:.8rem;color:var(--muted);margin-top:.3rem}
.acc-link{display:flex;gap:.4rem;margin-top:.5rem}
.acc-link input{flex:1;padding:.6rem .7rem;border:1.5px solid var(--line);border-radius:12px;font:inherit;font-size:.85rem}
.acc-link .btn{padding:.5rem 1rem}
.acc-prof{margin-top:1rem;border-top:1px solid var(--line);padding-top:.8rem}
.acc-prof summary{cursor:pointer;font-weight:800;color:var(--green);margin-bottom:.7rem}
.acc-out{display:block;margin:1rem auto 0;background:transparent;color:var(--red);font-weight:800;padding:.4rem 1rem}
@media(max-width:560px){.acc-bg{align-items:flex-end;padding:0}.acc-box{border-radius:22px 22px 0 0;max-height:94vh}}
.acc-box .btn-ghost{background:var(--bg);color:var(--green);border:1.5px solid var(--line);box-shadow:none}
.acc-cont{width:100%;margin-top:.3rem}
.acc-gift{border:1.5px dashed var(--gold);background:linear-gradient(135deg,#FFF9E8,#FBF8F2);border-radius:16px;padding:.8rem 1rem;margin:.7rem 0;text-align:right;font-size:.88rem}
.acc-gift .g-t{font-weight:900;color:var(--green);margin-bottom:.2rem}
.acc-gift .g-code{display:inline-block;margin-top:.2rem}.acc-gift .g-code b{background:var(--green);color:#fff;padding:.05rem .5rem;border-radius:6px;letter-spacing:1px}
.acc-gift .g-apply{margin-top:.5rem;padding:.5rem 1.2rem;font-size:.9rem}
.acc-gift.locked,.acc-gift.used,.acc-gift.expired{border-color:var(--line);background:var(--bg);color:var(--muted)}
.acc-trk-link{display:block;margin:.7rem auto 0;background:transparent;color:var(--green);font-weight:800;font-size:.85rem;text-decoration:underline}
.trk-steps{list-style:none;margin:1rem 0;padding:0;display:flex;flex-direction:column;gap:.5rem}
.trk-steps li{padding:.6rem .9rem;border-radius:12px;background:var(--bg);color:var(--muted);font-weight:700;border:1.5px solid var(--line)}
.trk-steps li.done{background:#E8F6EF;color:var(--ok);border-color:#BFE6D3}
.trk-steps li.now{background:var(--green);color:#fff;border-color:var(--green)}
.trk-bad{margin:1rem 0;padding:.8rem;border-radius:12px;background:#FDECEC;color:var(--red);font-weight:800}
.trk-meta{font-size:.85rem;color:var(--muted);line-height:1.9;border-top:1px solid var(--line);padding-top:.7rem}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

#bestsellers{transition:background .35s}
.coll-tabs{display:flex;gap:.6rem;overflow-x:auto;scroll-snap-type:x proximity;padding:.2rem .2rem 1rem;margin-bottom:.6rem;justify-content:center;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.coll-tabs::-webkit-scrollbar{display:none}
.coll-tabs button{flex:0 0 auto;scroll-snap-align:center;padding:.55rem 1.2rem;border-radius:999px;background:#fff;border:1.5px solid var(--line);font-weight:800;color:var(--ink);font-family:inherit;font-size:.92rem;cursor:pointer;white-space:nowrap;transition:background .25s,color .25s,transform .15s}
.coll-tabs button.on{color:#fff;transform:translateY(-1px);box-shadow:0 6px 16px rgba(0,0,0,.14)}
@media (max-width:640px){.coll-tabs{justify-content:flex-start}}

/* شريط التمرير: أكريليك برتقالي فلورسنت شفاف رقيق 6px بزوايا مدوّرة */
::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-track,::-webkit-scrollbar-corner{background:transparent}::-webkit-scrollbar-thumb{background:linear-gradient(180deg,rgba(255,158,52,.66),rgba(255,106,0,.52));border-radius:6px;box-shadow:inset 0 0 0 1px rgba(255,222,176,.6),inset 0 1px 0 rgba(255,255,255,.55),0 0 7px rgba(255,120,20,.4)}::-webkit-scrollbar-thumb:hover,::-webkit-scrollbar-thumb:active{background:linear-gradient(180deg,rgba(255,176,82,.82),rgba(255,120,10,.7))}@supports not selector(::-webkit-scrollbar){*{scrollbar-width:thin;scrollbar-color:rgba(255,128,24,.62) transparent}}

/* ── بطاقات أكريليك فلورسنت شفاف (أخضر/أزرق/أصفر/برتقالي بالتناوب) بزوايا مدوّرة ── */
.card,.feat,.review,.lp-card,.lp-textcard,.benefits,.form,.trust div,.mini-points div,.faq details{--ac:255,118,24;background:linear-gradient(145deg,rgba(var(--ac),.17),rgba(255,255,255,.62) 52%,rgba(var(--ac),.1));-webkit-backdrop-filter:blur(10px) saturate(1.35);backdrop-filter:blur(10px) saturate(1.35);border:1px solid rgba(var(--ac),.42);box-shadow:inset 0 1px 0 rgba(255,255,255,.9),inset 0 0 0 1px rgba(255,255,255,.4),0 10px 26px rgba(var(--ac),.18)}
.card,.feat,.review,.lp-card,.lp-textcard,.benefits,.form{border-radius:24px}
.trust div,.mini-points div,.faq details{border-radius:18px}
:is(.card,.feat,.review,.lp-card,.lp-textcard,.trust div,.mini-points div,.faq details):nth-child(4n+1){--ac:110,230,30}
:is(.card,.feat,.review,.lp-card,.lp-textcard,.trust div,.mini-points div,.faq details):nth-child(4n+2){--ac:50,140,255}
:is(.card,.feat,.review,.lp-card,.lp-textcard,.trust div,.mini-points div,.faq details):nth-child(4n+3){--ac:255,205,20}
:is(.card,.feat,.review,.lp-card,.lp-textcard,.trust div,.mini-points div,.faq details):nth-child(4n){--ac:255,110,20}

/* effet cristal لبطاقات الموقع الملوّنة: وجوه ضوئية مائلة ولمعة علوية وتوهّج داخلي */
.card,.feat,.review,.lp-card,.lp-textcard,.trust div,.mini-points div,.faq details{background:linear-gradient(115deg,rgba(255,255,255,0) 16%,rgba(255,255,255,.14) 22%,rgba(255,255,255,0) 29%,rgba(255,255,255,0) 52%,rgba(255,255,255,.08) 58%,rgba(255,255,255,0) 66%),radial-gradient(160px 60px at 16% 0%,rgba(255,255,255,.22),transparent 72%),linear-gradient(145deg,rgba(var(--ac),.17),rgba(255,255,255,.62) 52%,rgba(var(--ac),.1));box-shadow:inset 0 1px 0 rgba(255,255,255,.7),inset 0 -3px 8px rgba(var(--ac),.07),0 10px 26px rgba(var(--ac),.18)}


/* ═══════════════════════════════════════════════════════════════
   ALYSSUM 2026 — Glass / Fluorescent Pistachio Visual Layer
   UI/Builder-safe visual enhancement: no product logic changes.
   ═══════════════════════════════════════════════════════════════ */

:root{
  --bg:#050705;
  --card:rgba(14,22,16,.72);
  --ink:#F4F8F3;
  --muted:#A6B3AA;
  --green:#B7FF4A;
  --green-strong:#8DFF22;
  --green-deep:#16351D;
  --gold:#D6B45A;
  --gold-2:#F1D987;
  --line:rgba(183,255,74,.16);
  --shadow:0 20px 60px rgba(0,0,0,.42);
  --shadow-lg:0 28px 90px rgba(0,0,0,.56);
}

/* black canvas — preserves existing green/gold visual language */
html,body{background:#050705;color:var(--ink)}
body{
  background:
    radial-gradient(900px 420px at 78% -8%,rgba(183,255,74,.055),transparent 68%),
    radial-gradient(720px 420px at 8% 55%,rgba(24,95,45,.07),transparent 70%),
    #050705;
}
.topbar{
  background:rgba(8,13,9,.88);
  color:#DCE8DE;
  border-bottom:1px solid rgba(183,255,74,.09);
  backdrop-filter:blur(16px);
}
.topbar b{color:var(--green)}

header.site{
  background:rgba(4,7,5,.72);
  border-bottom:1px solid rgba(255,255,255,.07);
  box-shadow:0 10px 35px rgba(0,0,0,.22);
  backdrop-filter:blur(22px) saturate(145%);
}
.logo{color:#F5FAF5}
.logo span{color:var(--green)}
nav.menu a{color:#D8E2DB}
.hd-wa{
  background:linear-gradient(135deg,#C8FF67,#79E51D);
  color:#071006;
  box-shadow:0 8px 24px rgba(183,255,74,.18);
}
.cart-btn{background:rgba(183,255,74,.12);color:var(--green);border:1px solid rgba(183,255,74,.28)}

.hero{
  background:
    radial-gradient(600px 360px at 82% 20%,rgba(183,255,74,.13),transparent 65%),
    radial-gradient(450px 280px at 12% 90%,rgba(214,180,90,.08),transparent 70%),
    linear-gradient(145deg,#07110A,#0A1B10 48%,#061008);
  border-bottom:1px solid rgba(183,255,74,.10);
}
.hero::after{
  width:560px;height:560px;
  background:radial-gradient(circle,rgba(183,255,74,.09),transparent 68%);
  filter:blur(4px);
}
.hero h1 em{color:var(--green)}
.hero p{color:#C7D4CB}
.btn-gold{
  background:linear-gradient(135deg,#C8FF67,#86EA28);
  color:#081008;
  box-shadow:0 14px 38px rgba(183,255,74,.23);
}
.btn-gold:hover{box-shadow:0 18px 48px rgba(183,255,74,.32)}
.btn-ghost{
  background:rgba(255,255,255,.045);
  border:1px solid rgba(255,255,255,.18);
  backdrop-filter:blur(14px);
}
.hero-stats div,.hero-badge{
  background:rgba(255,255,255,.045)!important;
  border:1px solid rgba(255,255,255,.11)!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 18px 42px rgba(0,0,0,.28);
  backdrop-filter:blur(16px);
}
.hero-stats b{color:var(--green)}
.hero-imgbox{
  border:1px solid rgba(183,255,74,.25)!important;
  box-shadow:0 35px 90px rgba(0,0,0,.48),0 0 60px rgba(183,255,74,.10)!important;
  background:rgba(255,255,255,.035)!important;
  backdrop-filter:blur(20px);
}
.hero-imgbox img{filter:saturate(1.03) contrast(1.02)}

.hero-orb{
  position:absolute;display:block;border-radius:50%;pointer-events:none;z-index:3;
  filter:blur(.2px);mix-blend-mode:screen;
}
.orb-green{width:110px;height:110px;right:-20px;top:18%;background:radial-gradient(circle,rgba(183,255,74,.34),rgba(183,255,74,.02) 70%,transparent 72%);animation:alyFloat 5s ease-in-out infinite}
.orb-gold{width:90px;height:90px;left:3%;bottom:12%;background:radial-gradient(circle,rgba(241,217,135,.24),transparent 70%);animation:alyFloat 6.5s ease-in-out infinite reverse}
.hero-leaf-glow{position:absolute;inset:7% 7% auto auto;width:45%;height:45%;border-radius:50%;background:radial-gradient(circle,rgba(183,255,74,.10),transparent 68%);filter:blur(22px);pointer-events:none}
.hero-product-float{
  position:absolute;left:-16px;bottom:24px;z-index:5;
  display:flex;align-items:center;gap:.55rem;
  padding:.5rem .7rem .5rem .5rem;
  border:1px solid rgba(183,255,74,.24);
  background:rgba(5,9,6,.66);
  backdrop-filter:blur(18px) saturate(140%);
  border-radius:18px;color:#fff;font-size:.72rem;font-weight:900;
  box-shadow:0 18px 44px rgba(0,0,0,.4),0 0 25px rgba(183,255,74,.08);
  animation:alyFloat 6s ease-in-out infinite;
}
.hero-product-float img{width:48px;height:48px;object-fit:cover;border-radius:12px;border:1px solid rgba(183,255,74,.28)}
.hero-product-float span{color:var(--green)}

#categories,#products,#reviews,#faq{background:#050705!important}
#bestsellers,#features{background:#070B08!important}
.sec-title h2{color:#F5FAF5}
.sec-title p,.kicker{color:#9BAAA0}

.shop-cat{
  border-color:rgba(183,255,74,.14);
  box-shadow:0 18px 48px rgba(0,0,0,.36);
}
.shop-cat::before{
  background:linear-gradient(0deg,rgba(3,9,5,.94),rgba(3,9,5,.18) 72%,transparent)!important;
}
.shop-cat:hover::before{
  background:linear-gradient(0deg,rgba(45,91,24,.92),rgba(3,9,5,.16) 72%,transparent)!important;
}
.shop-cat:hover{box-shadow:0 24px 60px rgba(0,0,0,.5),0 0 28px rgba(183,255,74,.08)}

.card,.feat,.review,.lp-card,.lp-textcard,.benefits,.form,.trust div,.mini-points div,.faq details{
  --ac:183,255,74;
  color:#F2F7F3;
  background:
    linear-gradient(135deg,rgba(255,255,255,.055),rgba(255,255,255,.018) 52%,rgba(183,255,74,.025)),
    rgba(9,15,11,.68)!important;
  border:1px solid rgba(var(--ac),.20)!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.10),
    inset 0 -20px 45px rgba(0,0,0,.14),
    0 20px 55px rgba(0,0,0,.38)!important;
  backdrop-filter:blur(22px) saturate(145%);
  -webkit-backdrop-filter:blur(22px) saturate(145%);
  position:relative;
  overflow:hidden;
}
